function describe(node, depth) {
  const d = depth || 0;
  const pad = '  '.repeat(d);
  let out = pad + node.type + ' "' + node.name + '"';
  const props = [];
  if (node.type === 'FRAME' || node.type === 'COMPONENT' || node.type === 'RECTANGLE' || node.type === 'ELLIPSE' || node.type === 'ROUNDED_RECTANGLE' || node.type === 'VECTOR') {
    if ('fills' in node && Array.isArray(node.fills)) {
      props.push('fills=' + JSON.stringify(node.fills.map(f => ({ type: f.type, color: f.color, opacity: f.opacity, visible: f.visible }))));
    }
    if ('strokes' in node && Array.isArray(node.strokes)) {
      props.push('strokes=' + JSON.stringify(node.strokes.map(s => ({ type: s.type, color: s.color, visible: s.visible }))));
    }
    if ('cornerRadius' in node) props.push('cornerRadius=' + JSON.stringify(node.cornerRadius));
    if ('strokeWeight' in node) props.push('strokeWeight=' + node.strokeWeight);
  }
  if (node.type === 'TEXT') {
    const f = node.fontName;
    const fs = node.fontSize;
    const ca = node.characters;
    props.push('characters="' + ca + '"');
    props.push('font=' + (f ? f.family + ' ' + f.style : 'null') + ' size=' + fs);
    props.push('fills=' + JSON.stringify(node.fills.map(f => ({ color: f.color }))));
    props.push('textAlignHorizontal=' + node.textAlignHorizontal);
    props.push('lineHeight=' + JSON.stringify(node.lineHeight));
    props.push('letterSpacing=' + JSON.stringify(node.letterSpacing));
  }
  out += ' ' + props.join(' | ');
  if ('children' in node) {
    for (const c of node.children) out += '\n' + describe(c, d + 1);
  }
  return out;
}
