// Inspect icon fills
const iconIds = ['3:140','3:143','3:146','3:149','3:152','3:155','3:158','3:161','3:164'];
for (const id of iconIds) {
  const n = figma.getNodeById(id);
  if (n) {
    const fills = [];
    function collect(node) {
      if ('fills' in node && Array.isArray(node.fills)) {
        for (const f of node.fills) {
          if (f.visible !== false) fills.push(JSON.stringify(f.color || f.gradientStops));
        }
      }
      if ('children' in node) for (const c of node.children) collect(c);
    }
    collect(n);
    out += 'ICON ' + n.name + ' size=' + n.width + 'x' + n.height + ' colors=' + fills.join(',') + '\n';
  }
}
return out;

