  if ('fills' in node && Array.isArray(node.fills)) {
    bits.push('fills=' + JSON.stringify(node.fills.map(f => ({ type: f.type, visible: f.visible, color: f.color, opacity: f.opacity }))));
  }
  if ('strokes' in node && Array.isArray(node.strokes) && node.strokes.length) {
    bits.push('strokes=' + JSON.stringify(node.strokes.map(s => ({ type: s.type, visible: s.visible, color: s.color, weight: node.strokeWeight }))));
  }
  line += ' ' + bits.join(' | ');
  let out = line;
  if ('children' in node) {
    for (const c of node.children) out += '\n' + desc(c, (d||0) + 1);
