async function TXT(name,x,y,w,h,chars,size,weight,color,align='LEFT'){
  const n=figma.createText(); n.name=name; n.fontName={family:'Inter',style:weight}; n.fontSize=size;
  n.characters=chars; n.fills=[SOL(color)]; n.x=x; n.y=y; n.resize(w,h); n.textAutoResize='NONE';
