function colorize(node,c,alsoStrokes=true){
  const walk=n=>{
    if(n.type!=='FRAME'&&n.type!=='GROUP'&&n.type!=='INSTANCE'&&n.type!=='COMPONENT'){
      if('fills' in n && Array.isArray(n.fills) && n.fills.length){ n.fills=[SOL(c)]; }
