function describe(node, depth) {
  const o = { id: node.id, name: node.name, type: node.type };
  if (node.type === 'TEXT') o.text = node.characters;
  if (node.type === 'COMPONENT') {
    if (node.componentPropertyDefinitions) {
      o.props = Object.keys(node.componentPropertyDefinitions).map(k => ({ name: k, type: node.componentPropertyDefinitions[k].type, defaultValue: node.componentPropertyDefinitions[k].defaultValue }));
    }
  }
  if ('children' in node && depth < 3) {
    o.children = node.children.map(c => describe(c, depth + 1));
  }
  return o;
}
const out = [];
for (const id of ids) {
  const n = figma.getNodeById(id);
  if (n) out.push(describe(n, 0));
}
return JSON.stringify(out, null, 1).slice(0, 58000);

