    t.textAutoResize = 'HEIGHT';
    p.appendChild(t);
    return t;
  }
  function RX(p, name, x, y, w, h, fill, radius, stroke, sw) {
    const r = figma.createRectangle();
    r.name = name || 'rect';
    r.x = x; r.y = y; r.resize(w, h);
    if (radius !== undefined) r.cornerRadius = radius;
    r.fills = fill ? [{type:'SOLID', color: fill}] : [];
