    const pts = vals.map((v, i) => [x + i*(w/(vals.length-1)), y + h - ((v-min)/span)*h]);
    const dLine = pts.map((pt, i) => (i===0?'M ':'L ') + pt[0].toFixed(1) + ' ' + pt[1].toFixed(1)).join(' ');
    const lp = pts[pts.length-1], f0 = pts[0];
