Vectors for sparklines: draw with M/L commands and smooth? Simple polyline fine.

```js
function spark(parent, x, y, w, h, vals, up) {
  // normalize
  const min = Math.min(...vals), max = Math.max(...vals);
  const pts = vals.map((v,i)=>[x + i*(w/(vals.length-1)), y + h - ((v-min)/(max-min||1))*h]);
  const dLine = pts.map((p,i)=> (i===0?'M':'L') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' ');
  const dFill = dLine + ' L' + pts[pts.length-1][0].toFixed(1) + ' ' + (y+h) + ' L' + pts[0][0].toFixed(1) + ' ' + (y+h) + ' Z';
  const col = up ? C.up : C.down;
  const line = figma.createVector(); line.vectorPaths=[{windingRule:'NONZERO', data:dLine}];
  line.strokes=[{type:'SOLID', color:col}]; line.strokeWeight=1.6; line.fills=[];
  const fill = figma.createVector(); fill.vectorPaths=[{windingRule:'NONZERO', data:dFill}];
  fill.fills=[{type:'SOLID', color:col, opacity:0.08}]; fill.strokes=[];
  parent.appendChild(line); parent.appendChild(fill);
}
```

