(async function () {
  const out = [];
  function pageName(n) { let p = n; while (p.parent && p.parent.type !== 'PAGE') p = p.parent; return p.name; }
  (function walk(n) {
    if (n.type === 'COMPONENT' || n.type === 'COMPONENT_SET') {
      out.push(n.name + '#' + n.id + '@' + pageName(n) + '/' + n.parent.name);
    }
    if ('children' in n) for (const c of n.children) walk(c);
  })(figma.root);
  // Also page children of workspace
  const ws = figma.getNodeById('5:2');
  const wsLines = ['WS PAGE:', '  ' + ws.children.map(f => f.name + '(' + f.type + ')@' + Math.round(f.x) + ',' + Math.round(f.y)).join(' | ')];
