})();

(async function () {
  const page = figma.getNodeById('5:2');
  const lines = [];
  function pageName(n) { let p = n; while (p.parent && p.parent.type !== 'PAGE') p = p.parent; return p.name; }
  const comps = [];
  (function walk(n) {
    if (n.type === 'COMPONENT') comps.push(n);
    if ('children' in n) for (const c of n.children) walk(c);
  })(page);

  for (const comp of comps) {
    const parts = [];
    (function desc(n, depth) {
      let s = n.name;
      if (n.type === 'TEXT') s += ':"' + n.characters + '"';
      if (n.type === 'INSTANCE') { try { s += '[main=' + n.mainComponent.name + ']'; } catch(e) {} }
      parts.push(s);
      if ('children' in n && depth < 2) for (const c of n.children) desc(c, depth + 1);
    })(comp, 0);
    lines.push(comp.name + '(' + Math.round(comp.width) + 'x' + Math.round(comp.height) + ') :: ' + parts.join(' | '));
  }
  return lines.join('\n').slice(0, 55000);
})();

