(async () => {
  const comp = figma.getNodeById('3:125');
  if (!comp) return 'no comp';
  const out = [];
  (function walk(n, d) {
    let s = '  '.repeat(d) + n.type + ' ' + n.name + ' ' + Math.round(n.x) + ',' + Math.round(n.y) + ' ' + Math.round(n.width) + 'x' + Math.round(n.height);
    if (n.type === 'RECTANGLE' || n.type === 'ELLIPSE') s += ' fills=' + JSON.stringify(n.fills);
    if (n.type === 'VECTOR' || n.type === 'BOOLEAN_OPERATION') s += ' paths=' + (n.vectorPaths ? n.vectorPaths.length : 0);
    out.push(s);
    if ('children' in n) for (const c of n.children) walk(c, d + 1);
  })(comp, 0);
  // also try an instance
  const inst = comp.createInstance();
  const dt = inst.detachInstance();
  out.push('DETACHED: ' + dt.type + ' ' + dt.name + ' ' + dt.width + 'x' + dt.height);
  const shapes = dt.findAll(n => n.type === 'RECTANGLE' || n.type === 'VECTOR' || n.type === 'BOOLEAN_OPERATION');
  out.push('shapes: ' + shapes.map(s => s.type + ' ' + s.name).join(' | '));
  dt.remove();
  return out.join('\n');
})();

